DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT122-S2-Q10$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT122-S2-Q10$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Megan's Position$batch07$, $batch07$People pursue wealth beyond their basic needs only if they see it as a route to status or prestige.$batch07$), (1, $batch07$Channen's Position$batch07$, $batch07$"Not everybody thinks that way." Money buys whatever goods you want, even if you don't care what others think.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Megan's claim is a conditional: extra wealth requires a status motive. Channen refutes it by offering a different motive: buying goods you want. So they disagree about whether any other motive exists.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether status is the only motive for pursuing extra wealth.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT122-S2-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
